import json
from pathlib import Path
from common import ROOT, OUT, save

string=lambda n:{'type':'string','minLength':1,'maxLength':n}
identifier={'type':'string','pattern':'^[a-f0-9]{32}$'}
rule={'type':'object','properties':{'from':string(240),'value':{},'op':{'enum':['copy','text','decimal','integer','gtin','date_iso','date_dmy','boolean']},'required':{'type':'boolean'}},'oneOf':[{'required':['from'],'not':{'required':['value']}},{'required':['value'],'not':{'required':['from']}}],'additionalProperties':False}
fields={'type':'object','maxProperties':100,'propertyNames':{'pattern':'^/','maxLength':240},'additionalProperties':rule}
mapping={'$schema':'https://json-schema.org/draft/2020-12/schema','title':'OpenAliment declarative partner mapping v1','type':'object','required':['schema_version','fields'],'properties':{'schema_version':{'const':'openaliment.mapping.v1'},'fields':fields,'arrays':{'type':'array','maxItems':2,'items':{'type':'object','required':['from','to','fields'],'properties':{'from':string(240),'to':string(240),'fields':fields},'additionalProperties':False}}},'additionalProperties':False}
save('partner-mapping.schema.json',mapping)
receipt={'$schema':'https://json-schema.org/draft/2020-12/schema','title':'OpenAliment private digital receipt v1','type':'object','required':['schema_version','id','merchant','receipt_external_id','issued_at','lines','simulation'],'properties':{'schema_version':{'const':'openaliment.receipt.v1'},'id':identifier,'merchant':string(180),'receipt_external_id':string(120),'issued_at':{'type':'string','format':'date-time'},'simulation':{'type':'boolean'},'lines':{'type':'array','minItems':1,'maxItems':500,'items':{'type':'object','required':['line_id','name','gtin14','lot_code','quantity','unit','expiry'],'properties':{'line_id':string(80),'name':string(180),'gtin14':{'type':['string','null'],'pattern':'^[0-9]{14}$'},'lot_code':{'type':['string','null'],'maxLength':120},'quantity':{'type':'number','exclusiveMinimum':0,'maximum':100000},'unit':{'enum':['pack','g','ml']},'expiry':{'anyOf':[{'type':'null'},{'$ref':'/api/schemas/food-date.schema.json'}]}},'additionalProperties':False}}},'additionalProperties':False}
save('digital-receipt.schema.json',receipt)
envelope={'type':'object','required':['mapping_id','operation','payload'],'properties':{'mapping_id':identifier,'operation':{'enum':['product','batch','receipt']},'payload':{'type':'object'},'event_key':string(128),'external_id':string(120)},'additionalProperties':False}
api={'openapi':'3.1.0','info':{'title':'OpenAliment — conectoare pentru parteneri și bonuri digitale','version':'2.1.0','description':'Mapări declarative versionate pentru produse, loturi și bonuri digitale. Importul catalogului creează ciorne; publicarea, drepturile GS1 și licențierea se aprobă separat. API v1 rămâne compatibil.'},'servers':[{'url':'https://openaliment.ro'}],'components':{'securitySchemes':{'producerToken':{'type':'http','scheme':'bearer','description':'Producer token with read/write scope; approval uses separate v1 publish routes.'}},'schemas':{'Mapping':mapping,'Event':envelope,'Receipt':receipt}},'security':[{'producerToken':[]}],'paths':{}}
def operation(summary,body=None,write=False):
    out={'summary':summary,'responses':{str(201 if write else 200):{'description':'Operation result'},'401':{'description':'Authentication required'},'403':{'description':'Scope, role or origin denied'},'404':{'description':'Unknown object or other organization'},'409':{'description':'Immutable version, existing lot or idempotency conflict'},'422':{'description':'Validation or required approval missing'},'429':{'description':'Rate limit; retry with identical event'},'503':{'description':'Setup or service unavailable'}}}
    if body is not None:out['requestBody']={'required':True,'content':{'application/json':{'schema':body}}}
    if write:out['parameters']=[{'name':'Idempotency-Key','in':'header','required':True,'schema':{'type':'string','pattern':'^[A-Za-z0-9_.:-]{8,128}$'}}]
    return out
api['paths']['/api/v2/manage/connectors']={'get':operation('List own connectors'),'post':operation('Create a catalog or retail receipt connector',{'type':'object','required':['name','kind'],'properties':{'name':string(180),'kind':{'enum':['catalog','retail_receipt']}},'additionalProperties':False},True)}
base='/api/v2/manage/connectors/{connector_id}'
api['paths'][base+'/mappings']={'parameters':[{'name':'connector_id','in':'path','required':True,'schema':identifier}],'get':operation('List immutable mappings and hashes'),'post':operation('Create a new mapping version',{'type':'object','required':['version_key','mapping'],'properties':{'version_key':string(60),'mapping':{'$ref':'#/components/schemas/Mapping'}},'additionalProperties':False},True)}
for name in ['preview','ingest']:
    body={'allOf':[{'$ref':'#/components/schemas/Event'}]+([{'required':['event_key','external_id']}] if name=='ingest' else [])}
    api['paths'][base+'/'+name]={'parameters':[{'name':'connector_id','in':'path','required':True,'schema':identifier}],'post':operation('Validate/map without writes' if name=='preview' else 'Ingest one immutable external event atomically',body,name=='ingest')}
api['paths']['/api/v2/home/receipts/preview']={'post':{'summary':'Preview confidential receipt by capability; does not add inventory','security':[],'requestBody':{'required':True,'content':{'application/json':{'schema':{'type':'object','required':['token'],'properties':{'token':{'type':'string','pattern':'^[a-f0-9]{64}$'}},'additionalProperties':False}}}},'responses':{'200':{'description':'Private receipt; no-store','content':{'application/json':{'schema':{'$ref':'#/components/schemas/Receipt'}}}},'404':{'description':'Unknown or expired capability'},'429':{'description':'Rate limited'}}}}
save('integration-openapi.json',api)
